feed:
    {{ config.title }}
    {%- if config.description %}
    {{ config.description }}
    {%- endif %}


    Zola
    {# Zola's own feed sorting is by published date, which would hide projects that were
       written earlier but updated recently. Sort here by the later of the two dates
       instead, then keep the newest handful. #}
    {%- set projects = [{"page": project, "effective": project.updated | default(value=project.date, boolean=true)} for project in pages if project.extra.thread_id is defined] | sort(attribute="effective") | reverse %}
    {%- set entries = projects[:20] %}
    {%- if entries | length > 0 %}
    {{ entries[0].effective | date(format="%Y-%m-%dT%H:%M:%S%:z") }}
    {%- endif %}
    {{ feed_url | safe }}
    {%- for entry in entries %}
    {%- set page = entry.page %}
    {%- set is_updated = page.updated is defined and page.updated %}

        {% if is_updated %}Updated: {{ page.title }}{% else %}{{ page.title }}{% endif %}
        {{ page.date | date(format="%Y-%m-%dT%H:%M:%S%:z") }}
        {{ entry.effective | date(format="%Y-%m-%dT%H:%M:%S%:z") }}

            {{ page.extra.author_name }}


        {% if is_updated %}{{ page.permalink ~ "#updated-" ~ page.updated }}{% else %}{{ page.permalink }}{% endif %}
        {%- set hero = "" %}
        {%- if page.extra.hero is defined %}
        {%- set alt = page.title | escape %}
        {%- set hero = '
' %}
        {%- endif %}
        {{ hero ~ page.content }}

    {%- endfor %}
